def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = 4

    # Find a full horizontal or vertical line of a single non-background color.
    line = None
    for r in range(h):
        if grid[r][0] != bg and all(x == grid[r][0] for x in grid[r]):
            line = ("h", r, grid[r][0])
            break
    if line is None:
        for c in range(w):
            if grid[0][c] != bg and all(grid[r][c] == grid[0][c] for r in range(h)):
                line = ("v", c, grid[0][c])
                break

    out = [[bg] * w for _ in range(h)]
    if line is None:
        return [row[:] for row in grid]

    direction, pos, line_color = line
    if direction == "h":
        out[pos] = [line_color] * w
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] != bg and r != pos]
        if not cells:
            return out
        rmin = min(r for r, c in cells)
        rmax = max(r for r, c in cells)
        below = (rmin + rmax) / 2 > pos
        new_min = pos + 1 if below else pos - (rmax - rmin) - 1
        shift = new_min - rmin
        for r, c in cells:
            out[r + shift][c] = grid[r][c]
        marker = new_min + (rmax - rmin) + 1 if below else new_min - 1
        if 0 <= marker < h:
            out[marker] = [8] * w
    else:
        for r in range(h):
            out[r][pos] = line_color
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] != bg and c != pos]
        if not cells:
            return out
        cmin = min(c for r, c in cells)
        cmax = max(c for r, c in cells)
        right = (cmin + cmax) / 2 > pos
        new_min = pos + 1 if right else pos - (cmax - cmin) - 1
        shift = new_min - cmin
        for r, c in cells:
            out[r][c + shift] = grid[r][c]
        marker = new_min + (cmax - cmin) + 1 if right else new_min - 1
        if 0 <= marker < w:
            for r in range(h):
                out[r][marker] = 8

    return out
